page Sim "/" {
  meta title="Simulación de pelotas"

  state count = 0
  state frames = 0
  state paused = false

  ref box
  ref ctx
  ref balls
  ref raf

  fn newBall() {
    let r = 10
    let W = 400
    let H = 300
    return {
      x: r + Math.random() * (W - 2 * r),
      y: r + Math.random() * (H - 2 * r),
      vx: (Math.random() * 2 - 1) * 4,
      vy: (Math.random() * 2 - 1) * 4,
      r: r
    }
  }

  fn clamp(b) {
    let W = 400
    let H = 300
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > W - b.r {
      b.x = W - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > H - b.r {
      b.y = H - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minDist = a.r + b.r
        if dist < minDist {
          if dist == 0 {
            dx = 1
            dy = 0
            dist = 1
          }
          let nx = dx / dist
          let ny = dy / dist
          let approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny
          if approaching < 0 {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = b.vx
            a.vy = b.vy
            b.vx = tvx
            b.vy = tvy
          }
          let overlap = (minDist - dist) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          b.x += nx * overlap
          b.y += ny * overlap
          clamp(a)
          clamp(b)
        }
      }
    }
  }

  fn draw() {
    if !ctx { return }
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn tick() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn startLoop() {
    if raf != null { return }
    raf = requestAnimationFrame(tick)
  }

  fn stopLoop() {
    if raf != null {
      cancelAnimationFrame(raf)
    }
    raf = null
  }

  fn makeBalls() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(newBall())
    }
    return list
  }

  fn add() {
    balls.push(newBall())
    count = balls.length
    if paused { draw() }
  }

  fn toggle() {
    if paused {
      paused = false
      startLoop()
    } else {
      paused = true
      stopLoop()
    }
  }

  fn reset() {
    balls = makeBalls()
    count = balls.length
    frames = 0
    if paused { draw() }
  }

  mount {
    ctx = box.getContext("2d")
    balls = makeBalls()
    count = balls.length
    frames = 0
    raf = null
    startLoop()
    cleanup { stopLoop() }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas" tag=h1
    canvas id="sim" ref=box width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

page Sim "/" {
  meta title="Simulación de pelotas"

  state total = 0
  state frames = 0
  state paused = false

  ref box
  ref ctx
  ref balls
  ref raf

  fn rand(a, b) {
    return a + Math.random() * (b - a)
  }

  fn makeBall() {
    let R = 10
    let b = null
    for (let tries = 0; tries < 50; tries++) {
      b = { x: rand(R, 400 - R), y: rand(R, 300 - R), vx: rand(-3, 3), vy: rand(-3, 3), color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)` }
      let ok = true
      if balls {
        for (let i = 0; i < balls.length; i++) {
          let o = balls[i]
          if Math.hypot(o.x - b.x, o.y - b.y) < 2 * R {
            ok = false
            break
          }
        }
      }
      if ok { break }
    }
    return b
  }

  fn clamp(b) {
    let R = 10
    if b.x < R {
      b.x = R
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - R {
      b.x = 400 - R
      b.vx = -Math.abs(b.vx)
    }
    if b.y < R {
      b.y = R
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - R {
      b.y = 300 - R
      b.vy = -Math.abs(b.vy)
    }
  }

  fn step() {
    let R = 10
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.hypot(dx, dy)
        if dist < 2 * R {
          let approaching = (c.vx - a.vx) * dx + (c.vy - a.vy) * dy < 0
          if approaching {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          if dist == 0 {
            dx = 1
            dy = 0
            dist = 1
          }
          let overlap = (2 * R - dist) / 2
          let nx = dx / dist
          let ny = dy / dist
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          clamp(a)
          clamp(c)
        }
      }
    }
  }

  fn draw() {
    if !ctx { return }
    ctx.clearRect(0, 0, 400, 300)
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, 10, 0, Math.PI * 2)
      ctx.fillStyle = b.color
      ctx.fill()
    }
  }

  fn tick() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn newBalls() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    total = balls.length
  }

  fn add() {
    balls.push(makeBall())
    total = balls.length
    if paused { draw() }
  }

  fn toggle() {
    paused = !paused
    if paused {
      cancelAnimationFrame(raf)
      raf = null
    } else {
      raf = requestAnimationFrame(tick)
    }
  }

  fn restart() {
    newBalls()
    frames = 0
    draw()
  }

  mount {
    ctx = box.getContext("2d")
    newBalls()
    draw()
    raf = requestAnimationFrame(tick)
    cleanup {
      if raf { cancelAnimationFrame(raf) }
    }
  }

  style {
    .sim-canvas { border: 1px solid var(--a-border); background: #fafafa; }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas" tag=h1
    canvas ref=box width=400 height=300 id="sim" class="sim-canvas"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> restart()
    }
    row gap=4 {
      text `Pelotas: ${total}`
      text `Cuadros: ${frames}`
    }
  }
}
